  ["Kimia||Ikatan Kimia||Ikatan Logam dan Antarmolekul"]: [
    {"question":"Apa yang menjadi ciri khas ikatan logam?","options":["A. Transfer elektron antar atom","B. Pemakaian bersama pasangan elektron","C. Lautan elektron yang terdelokalisasi","D. Gaya tarik elektrostatik antara ion positif dan negatif"],"correctIndex":2,"difficulty":"easy","explanation":"Ikatan logam terbentuk dari delokalisasi elektron valensi, membentuk 'lautan elektron' yang mengelilingi kation logam."},
    {"question":"Gaya antarmolekul manakah yang paling lemah?","options":["A. Ikatan hidrogen","B. Gaya dipol-dipol","C. Gaya London","D. Ikatan ion"],"correctIndex":2,"difficulty":"easy","explanation":"Gaya London adalah gaya dispersi sementara yang paling lemah dibandingkan ikatan hidrogen dan gaya dipol-dipol."},
    {"question":"Pasangan molekul manakah yang dapat membentuk ikatan hidrogen satu sama lain?","options":["A. CH₄ dan CCl₄","B. H₂O dan NH₃","C. CO₂ dan H₂","D. HCl dan H₂S"],"correctIndex":1,"difficulty":"medium","explanation":"Ikatan hidrogen terjadi antara atom H dengan atom N, O, atau F yang sangat elektronegatif. H₂O dan NH₃ masing-masing memiliki atom H yang terikat pada O dan N, sehingga dapat saling membentuk ikatan hidrogen."},
    {"question":"Mengapa logam dapat ditempa menjadi lembaran tipis?","options":["A. Karena adanya ikatan kovalen yang kuat antar atom","B. Karena elektron terdelokalisasi memungkinkan lapisan atom bergeser","C. Karena ikatan ion mudah putus saat ditekan","D. Karena ikatan hidrogen dapat meregang"],"correctIndex":1,"difficulty":"medium","explanation":"Elektron terdelokalisasi dalam ikatan logam bertindak sebagai perekat yang fleksibel, sehingga lapisan atom dapat bergeser tanpa memutus ikatan, menghasilkan sifat malleable."},
    {"question":"Titik didih H₂O jauh lebih tinggi daripada H₂S, meskipun massa molekul H₂S lebih besar. Hal ini disebabkan oleh...","options":["A. Gaya London yang lebih kuat pada H₂O","B. Ikatan hidrogen pada H₂O","C. Gaya dipol-dipol pada H₂S","D. Ikatan logam pada H₂O"],"correctIndex":1,"difficulty":"hard","explanation":"H₂O memiliki ikatan hidrogen yang kuat antarmolekul, sedangkan H₂S hanya memiliki gaya dipol-dipol dan London yang lebih lemah, sehingga titik didih H₂O lebih tinggi."},
  ],

  ["Kimia||Stoikiometri||Konsep Mol"]: [
    {"question":"1 mol zat setara dengan jumlah partikel sebanyak ...","options":["A. 6,02 × 10²² partikel","B. 6,02 × 10²³ partikel","C. 12,04 × 10²³ partikel","D. 6,02 × 10²⁴ partikel","E. 3,01 × 10²³ partikel"],"correctIndex":1,"difficulty":"easy","explanation":"1 mol sama dengan 6,02 × 10²³ partikel. Angka ini dikenal sebagai bilangan Avogadro (L)."},
    {"question":"Massa molar karbon (C) = 12 g/mol. Berapa mol terdapat dalam 60 g karbon?","options":["A. 0,2 mol","B. 0,5 mol","C. 2 mol","D. 5 mol","E. 720 mol"],"correctIndex":3,"difficulty":"easy","explanation":"n = massa / Mr = 60 g / 12 g/mol = 5 mol."},
    {"question":"Volume 0,5 mol gas ideal pada keadaan STP adalah ...","options":["A. 5,6 L","B. 11,2 L","C. 22,4 L","D. 44,8 L","E. 112 L"],"correctIndex":1,"difficulty":"medium","explanation":"Pada STP, 1 mol gas = 22,4 L. Jadi 0,5 mol = 0,5 × 22,4 = 11,2 L."},
    {"question":"Jumlah mol NH₃ yang mengandung 1,806 × 10²⁴ molekul adalah ...","options":["A. 0,5 mol","B. 1 mol","C. 2 mol","D. 3 mol","E. 4 mol"],"correctIndex":3,"difficulty":"medium","explanation":"n = jumlah partikel / L = 1,806 × 10²⁴ / 6,02 × 10²³ = 3 mol."},
    {"question":"Massa 5,6 L gas X pada STP adalah 11 g. Massa molar gas X tersebut adalah ...","options":["A. 11 g/mol","B. 22 g/mol","C. 33 g/mol","D. 44 g/mol","E. 55 g/mol"],"correctIndex":3,"difficulty":"hard","explanation":"n = V / 22,4 = 5,6 / 22,4 = 0,25 mol. Mr = massa / n = 11 / 0,25 = 44 g/mol."},
  ],

