  ["Kimia||Asam dan Basa||Teori Asam Basa (Arrhenius, Bronsted-Lowry, Lewis)"]: [
    {"question":"Menurut teori Arrhenius, suatu zat dikategorikan sebagai asam jika dalam air menghasilkan ion...","options":["H+","OH−","Na+","Cl−"],"correctIndex":0,"difficulty":"easy","explanation":"Arrhenius mendefinisikan asam sebagai zat yang meningkatkan konsentrasi ion H+ (atau H3O+) ketika dilarutkan dalam air."},
    {"question":"Menurut teori asam-basa Bronsted-Lowry, basa adalah zat yang...","options":["Menerima proton (H+)","Mendonorkan proton (H+)","Menerima pasangan elektron","Mendonorkan pasangan elektron"],"correctIndex":0,"difficulty":"easy","explanation":"Bronsted-Lowry mendefinisikan basa sebagai akseptor proton (penerima H+), sedangkan asam adalah donor proton."},
    {"question":"Perhatikan reaksi berikut: NH3(aq) + H2O(l) ⇌ NH4+(aq) + OH−(aq). Pasangan asam-basa konjugasi yang tepat adalah...","options":["NH3 dan H2O","NH3 dan NH4+","NH4+ dan OH−","H2O dan NH4+"],"correctIndex":1,"difficulty":"medium","explanation":"NH3 adalah basa karena menerima proton, sedangkan NH4+ adalah asam konjugasi yang terbentuk setelah NH3 menerima proton. Jadi pasangan konjugasinya adalah NH3/NH4+."},
    {"question":"Di antara spesi berikut, yang dapat bertindak sebagai asam Lewis adalah...","options":["NH3","BF3","H2O","Cl−"],"correctIndex":1,"difficulty":"medium","explanation":"Asam Lewis adalah akseptor pasangan elektron. BF3 memiliki atom boron yang kekurangan elektron (oktet tidak lengkap), sehingga dapat menerima pasangan elektron dari basa Lewis. NH3, H2O, dan Cl− justru cenderung bertindak sebagai basa Lewis (donor pasangan elektron)."},
    {"question":"Spesi berikut yang bersifat amfoter menurut Bronsted-Lowry adalah...","options":["HCl","HCO3−","CO3^2−","NH4+"],"correctIndex":1,"difficulty":"hard","explanation":"HCO3− bersifat amfoter karena dapat mendonorkan proton menjadi CO3^2− dan dapat menerima proton menjadi H2CO3. HCl hanya asam, sedangkan CO3^2− dan NH4+ masing-masing hanya basa dan asam."},
  ],

  ["Kimia||Teori Asam Basa||Keasaman (pH) dari asam dan basa"]: [
    {"question":"Nilai pH larutan dengan [H⁺] = 10⁻³ M adalah...","options":["3","11","3 × 10⁻³","10³"],"correctIndex":0,"explanation":"pH = -log[H⁺] = -log(10⁻³) = 3."},
    {"question":"Larutan dengan pH = 2 bersifat...","options":["Netral","Basa","Asam kuat","Asam lemah"],"correctIndex":2,"explanation":"pH < 7 menunjukkan larutan bersifat asam. Nilai pH yang jauh di bawah 7 (seperti 2) mengindikasikan konsentrasi ion H+ yang tinggi, sehingga dikategorikan sebagai asam kuat."},
    {"question":"Jika [OH⁻] = 10⁻⁴ M, maka pOH dan pH larutan berturut-turut adalah...","options":["4 dan 10","10 dan 4","4 dan 4","10 dan 10"],"correctIndex":0,"explanation":"pOH = -log[OH⁻] = -log(10⁻⁴) = 4. pH = 14 - pOH = 14 - 4 = 10."},
    {"question":"pH campuran asam kuat dan basa kuat pada titik ekuivalen titrasi adalah...","options":["< 7","> 7","= 7","Bervariasi tergantung jenis asam"],"correctIndex":2,"explanation":"Pada titik ekuivalen, asam kuat dan basa kuat tepat habis bereaksi menghasilkan garam netral (ion-ion tidak terhidrolisis), sehingga pH = 7."},
    {"question":"Berapakah pH larutan HCl 0,001 M?","options":["1","2","3","4"],"correctIndex":2,"explanation":"HCl adalah asam kuat, sehingga [H+] = 0,001 M = 1×10^-3 M. pH = -log(1×10^-3) = 3."},
    {"question":"Berapakah pH larutan NaOH 0,01 M?","options":["12","13","2","11"],"correctIndex":0,"explanation":"NaOH adalah basa kuat, sehingga [OH-] = 0,01 M = 1×10^-2 M. pOH = -log(1×10^-2) = 2, pH = 14 - 2 = 12."},
  ],

